// For each connected shop: refresh the access token if it expires within
// the next 60s, then fetch receipts paid since the watermark. Emit one
// 'receipt' item per new receipt and one 'watermark' item per shop so the
// downstream Switch can route them to different DB writes.
const out = [];
const clientId = process.env.ETSY_CLIENT_ID;
if (!clientId) throw new Error('ETSY_CLIENT_ID not set');

for (const item of $input.all()) {
  const shop = item.json;
  let access  = shop.oauth_token;
  let refresh = shop.refresh_token;
  let expires = shop.token_expires;

  const expMs = expires ? new Date(expires).getTime() : 0;
  if (expMs - Date.now() < 60_000) {
    const tok = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.etsy.com/v3/public/oauth/token',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({
        grant_type: 'refresh_token', client_id: clientId, refresh_token: refresh
      }).toString(),
      json: true,
      timeout: 30000
    });
    if (!tok.access_token) {
      out.push({ json: { _kind: 'error', shop_pk: shop.id, error: `refresh failed: ${JSON.stringify(tok)}` } });
      continue;
    }
    access  = tok.access_token;
    refresh = tok.refresh_token;
    expires = new Date(Date.now() + (tok.expires_in - 60) * 1000).toISOString();
  }

  // Etsy receipts API: filter by min_created (unix seconds) for the watermark.
  const watermarkSec = Math.floor(new Date(shop.watermark).getTime() / 1000);
  let offset = 0;
  const limit = 50;
  let received = 0;
  while (true) {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://openapi.etsy.com/v3/application/shops/${shop.etsy_shop_id}/receipts`,
      headers: { Authorization: `Bearer ${access}`, 'x-api-key': clientId },
      qs: { limit, offset, was_paid: true, min_created: watermarkSec },
      json: true,
      timeout: 30000
    });
    const results = res.results || [];
    for (const r of results) {
      const total = (r.grandtotal && r.grandtotal.amount && r.grandtotal.divisor)
        ? r.grandtotal.amount / r.grandtotal.divisor
        : null;
      out.push({ json: {
        _kind: 'receipt',
        shop_pk: shop.id,
        etsy_order_id: String(r.receipt_id),
        status: r.status || (r.is_paid ? 'paid' : 'unknown'),
        total,
        line_items: r.transactions || [],
        raw: r
      } });
      received++;
    }
    if (results.length < limit) break;
    offset += limit;
    if (offset > 500) break; // safety
  }

  out.push({ json: {
    _kind: 'watermark',
    shop_pk: shop.id,
    oauth_token: access,
    refresh_token: refresh,
    token_expires: expires,
    received
  } });
}

return out;
